export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-mol-0001", "section": "service", "who": "reader", "text": "Во имя Отца, и Сына, и Святого Духа. Аминь."},
  {"id": "ru-mol-0002", "section": "service", "who": "rubric", "text": "Затем немного подожди, пока все чувства твои не придут в тишину и мысли твои не оставят все земное, и тогда произноси следующие молитвы, без поспешности и со вниманием сердечным:"},
  {"id": "ru-mol-0003", "section": "service", "who": "rubric", "text": "Молитва мытаря (Лк.18:13)"},
  {"id": "ru-mol-0004", "section": "service", "who": "reader", "text": "Боже, будь милостив ко мне грешному."},
  {"id": "ru-mol-0005", "section": "service", "who": "rubric", "text": "Начало обычное"},
  {"id": "ru-mol-0006", "section": "service", "who": "rubric", "text": "Молитва предначинательная"},
  {"id": "ru-mol-0007", "section": "service", "who": "reader", "text": "Господи Иисусе Христе, Сын Божий, по молитвам Пречистой Твоей Матери и всех святых, помилуй нас. Аминь."},
  {"id": "ru-mol-0008", "section": "service", "who": "rubric", "text": "Молитва Святому Духу"},
  {"id": "ru-mol-0009", "section": "service", "who": "reader", "text": "Царь Небесный, Утешитель (Советник, Наставник), Дух истины, везде сущий (находящийся) и все наполняющий (присутствием Своим), Сокровище благ и Податель жизни, прииди и поселись в нас (среди нас), очисти нас от всякого греха и спаси, Преблагий, души наши."},
  {"id": "ru-mol-0010", "section": "service", "who": "rubric", "text": "Трисвятое"},
  {"id": "ru-mol-0011", "section": "service", "who": "reader", "text": "Святой Боже, Святой Крепкий, Святой Бессмертный, помилуй нас."},
  {"id": "ru-mol-0012", "section": "service", "who": "reader", "text": "Слава Отцу и Сыну и Святому Духу, и ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0013", "section": "service", "who": "rubric", "text": "Молитва ко Пресвятой Троице"},
  {"id": "ru-mol-0014", "section": "service", "who": "reader", "text": "Пресвятая Троица, помилуй нас. Господи, очисти грехи наши. Владыка, прости беззакония наши. Святый, посети и исцели немощи наши, имени Твоего ради."},
  {"id": "ru-mol-0015", "section": "service", "who": "reader", "text": "Слава Отцу, и Сыну, и Святому Духу, и ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0016", "section": "service", "who": "rubric", "text": "Молитва Господня"},
  {"id": "ru-mol-0017", "section": "service", "who": "reader", "text": "Отче наш, Который на небесах! Да святится имя Твое, да приидет Царствие Твое; да будет воля Твоя и на земле, как на небе; хлеб наш насущный дай нам на сей день; и прости нам долги наши, как и мы прощаем должникам нашим; и не введи нас в искушение, но избавь нас от лукавого."},
  {"id": "ru-mol-0018", "section": "service", "who": "rubric", "text": "Тропари Троичные"},
  {"id": "ru-mol-0019", "section": "service", "who": "reader", "text": "Восстав от сна, припадаем к Тебе, Благой, и ангельскую песнь возглашаем Тебе, Сильный: «Свят, Свят, Свят Ты, Боже, по молитвам Богородицы помилуй нас!»"},
  {"id": "ru-mol-0020", "section": "service", "who": "reader", "text": "С постели и от сна Ты поднял меня, Господи! / Ум мой просвети и сердце, / и уста мои отверзи, / чтобы воспевать Тебя, Святая Троица: / «Свят, Свят, Свят Ты, Боже, / по молитвам Богородицы помилуй нас!»"},
  {"id": "ru-mol-0021", "section": "service", "who": "reader", "text": "Внезапно Судия придёт, и дела каждого обнаружатся. Но в страхе воскликнем в полночь: «Свят, Свят, Свят Ты, Боже, по молитвам Богородицы помилуй нас!»"},
  {"id": "ru-mol-0022", "section": "service", "who": "rubric", "text": "Молитва ко Пресвятой Троице"},
  {"id": "ru-mol-0023", "section": "service", "who": "reader", "text": "Восстав от сна, благодарю Тебя, Святая Троица, что по великой Твоей благости и долготерпению, Ты, Боже, не прогневался на меня, ленивого и грешного, и не погубил меня с беззакониями моими, но оказал мне обычное Твоё человеколюбие, и поднял меня, в бесчувствии лежащего, чтобы я рано утром к Тебе обратился и славословил власть Твою. И ныне просвети взоры мыслей моих, отверзи уста мои, чтобы мне поучаться слову Твоему, и уразумевать заповеди Твои, и творить волю Твою, и петь, прославляя Тебя от сердца, и воспевать всесвятое имя Твоё, Отца, и Сына, и Святого Духа ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0024", "section": "service", "who": "reader", "text": "Придите, поклонимся Царю нашему, Богу."},
  {"id": "ru-mol-0025", "section": "service", "who": "reader", "text": "Придите, поклонимся и припадем ко Христу, Царю, нашему Богу."},
  {"id": "ru-mol-0026", "section": "service", "who": "reader", "text": "Придите, поклонимся и припадем к Самому Христу, Царю и Богу нашему."},
  {"id": "ru-mol-0027", "section": "service", "who": "rubric", "text": "Псалом 50"},
  {"id": "ru-mol-0028", "section": "service", "who": "reader", "text": "Помилуй меня, Боже, по великой милости Твоей и по множеству щедрот Твоих изгладь беззаконие моё; совершенно омой меня от беззакония моего, и от греха моего очисти меня. Ибо беззаконие моё я знаю, и грех мой всегда предо мною. Тебе, Единому, я согрешил и злое пред Тобою сотворил, – да будешь оправдан в словах Твоих и победишь, если вступят с Тобою в суд. Ибо вот, я в беззакониях зачат, и во грехах родила меня мать моя. Ибо вот, Ты истину возлюбил, сокрытое и тайное премудрости Твоей мне открыл. Ты окропишь меня иссопом – и буду очищен; омоешь меня – и сделаюсь белее снега, дашь мне услышать радость и веселие – возрадуются кости униженные. Отврати лицо Твоё от грехов моих и все беззакония мои изгладь. Сердце чистое сотвори во мне, Боже, и Дух Правый обнови внутри меня. Не отринь меня от лица Твоего и Духа Твоего Святого не отними от меня. Возврати мне радость спасения Твоего и Духом Владычественным утверди меня. Научу беззаконных путям Твоим, и нечестивые к Тебе обратятся. Избавь меня от кровей, Боже, Боже спасения моего, возрадуется язык мой правде Твоей. Господи, Ты откроешь уста мои, и уста мои возвестят хвалу Твою. Ибо если бы жертвы Ты восхотел, я дал бы её, – к всесожжениям не будешь благоволить. Жертва Богу – дух сокрушённый, сердца сокрушённого и смиренного Бог не презрит. Облагодетельствуй, Господи, во благоволении Твоём Сион, и да будут воздвигнуты стены Иерусалима, – тогда примешь благосклонно жертву правды, возношение и всесожжения, тогда возложат на алтарь Твой тельцов."},
  {"id": "ru-mol-0029", "section": "service", "who": "rubric", "text": "Символ веры"},
  {"id": "ru-mol-0030", "section": "service", "who": "reader", "text": "Верую во единого Бога, Отца, Вседержителя, Творца неба и земли, всего и видимого и невидимого. И во единого Господа Иисуса Христа, Сына Божия, Единородного, от Отца рожденного прежде всех веков, Света от Света, Бога истинного от Бога истинного, рожденного, несотворенного, единосущного Отцу, через Которого всё произошло. Ради нас, людей, и нашего ради спасения сошедшего с небес, и воплотившегося от Духа Святого и Марии Девы, и вочеловечившегося. Распятого же за нас при Понтии Пилате, и страдавшего, и погребенного. И воскресшего в третий день, по Писаниям. И восшедшего на небеса, и сидящего справа от Отца. И снова грядущего со славою судить живых и мёртвых, и Царству Его не будет конца. И в Духа Святого, Господа, Животворящего, от Отца исходящего, со Отцом и Сыном равно поклоняемого и славимого, говорившего чрез пророков. Во единую, святую, соборную и апостольскую Церковь. Признаю одно Крещение для прощения грехов. Ожидаю воскресения мёртвых и жизни будущего века. Аминь."},
  {"id": "ru-mol-0031", "section": "service", "who": "rubric", "text": "Молитвы прп. Макария Великого (†390)"},
  {"id": "ru-mol-0032", "section": "service", "who": "rubric", "text": "Молитва 1-я"},
  {"id": "ru-mol-0033", "section": "service", "who": "reader", "text": "Боже, очисти меня, грешного, ибо я никогда не делал доброго пред Тобою, но избавь меня от зла и да будет во мне воля Твоя, чтобы мне не в осуждение открыть уста мои недостойные и восхвалить имя Твоё святое, Отца, и Сына, и Святого Духа ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0034", "section": "service", "who": "rubric", "text": "Молитва 2-я"},
  {"id": "ru-mol-0035", "section": "service", "who": "reader", "text": "Восстав от сна, полночную песнь приношу Тебе, Спаситель, и, припадая к стопам Твоим, взываю Тебе: не дай мне уснуть во греховной смерти, но сжалься надо мною, добровольно претерпевший распятие, и скоро подними меня, беспечно лежащего, и спаси меня, стоящего пред Тобою на молитве. И после сна ночного пошли мне ясный день безгрешный, Христе Боже, и спаси меня."},
  {"id": "ru-mol-0036", "section": "service", "who": "rubric", "text": "Молитва 3-я"},
  {"id": "ru-mol-0037", "section": "service", "who": "reader", "text": "К Тебе, Владыка Человеколюбец, восстав от сна я спешу, и за дела Тебе угодные принимаюсь, по милосердию Твоему, и молюсь Тебе: помоги мне во всякое время, во всяком деле, и избавь меня от всякой злой превратности в мире сем и от диавольского содействия, и спаси меня, и введи в Царство Твоё вечное. Ибо Ты – мой Творец и всякого блага Промыслитель и Податель. И в Тебе – вся надежда моя, и Тебе славу воссылаю, ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0038", "section": "service", "who": "rubric", "text": "Молитва 4-я"},
  {"id": "ru-mol-0039", "section": "service", "who": "reader", "text": "Господи, Ты по многой Твоей благости и великому милосердию Твоему дал мне, рабу Твоему, минувшее время ночи сей пройти без напасти от всякого зла противника. Ты Сам, Владыка, Творец всего, удостой меня истинным Твоим светом и просвещенным сердцем творить волю Твою, ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0040", "section": "service", "who": "rubric", "text": "Молитва 5-я свт. Василия Великого (†379) к Богу Отцу"},
  {"id": "ru-mol-0041", "section": "service", "who": "reader", "text": "Господи Вседержитель, Боже бесплотных Сил и всякой плоти, на высотах небесных живущий и озирающий долы земные, испытывающий и сердца, и внутренние чувства и сокровенное людей знающий ясно, Безначальный и Вечный Свет, у Которого нет изменения и ни тени перемены! Сам, бессмертный Царь, прими моления наши, которые мы, дерзновенно надеясь на множество милостей Твоих, в настоящее время [ночи] от скверных уст Тебе приносим, и прости нам согрешения наши, делом, и словом, и мыслию, сознательно и по неведению совершённые нами, и очисти нас от всякой скверны плоти и духа, [делая нас храмами Святого Твоего Духа]. И даруй нам с бодрствующим сердцем и трезвым разумом всю ночь нашей нынешней жизни пройти, ожидая пришествия светлого дня явления Единородного Твоего Сына, Господа и Бога и Спасителя нашего Иисуса Христа, когда Он, Судия всех, придёт на землю со славою воздать каждому по делам его; да найдет Он нас не падшими и обленившимися, но бодрствующими и поднявшимися, при исполнении заповедей Его, и готовыми войти с Ним в радость и Божественный чертог Его славы, где празднующих глас непрестанный и невыразимое наслаждение созерцающих несказанную красоту лица Твоего. Ибо Ты истинный Свет, просвещающий и освящающий всё, и Тебя воспевает всё творение во веки веков. Аминь."},
  {"id": "ru-mol-0042", "section": "service", "who": "rubric", "text": "Молитва 6-я свт. Василия Великого (†379) ко Пресвятой Троице"},
  {"id": "ru-mol-0043", "section": "service", "who": "reader", "text": "Тебя благословляем, Всевышний Боже и Господи милости, всегда творящего с нами дела великие и непостижимые, славные же и ужасные, которым нет числа, подавшего нам сон для упокоения немощи нашей и для отдыха от трудов многотрудной плоти. Благодарим Тебя, ибо Ты не погубил нас с беззакониями нашими, но явил Свое человеколюбие, как обычно, и нас, в бесчувствии сна лежащих, воздвиг для славословия могущества Твоего. Поэтому мы молим безмерную Твою благость: просвети наши мысленные очи и ум наш от тяжкого сна беспечности воздвигни. Отверзи уста наши и наполни их хвалою Тебе, дабы мы смогли непоколебимо воспевать, [восхвалять] и славить Тебя, во всех и от всех прославляемого Бога, Безначального Отца со Единородным Твоим Сыном и Всесвятым, и Благим, и Животворящим Твоим Духом, ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0044", "section": "service", "who": "rubric", "text": "Молитва 7-я, ко Пресвятой Богородице"},
  {"id": "ru-mol-0045", "section": "service", "who": "reader", "text": "Воспеваю благодать Твою, Владычица, молю Тебя, ум мой облагодатствуй. Наставь меня ходить право путем Христовых заповедей. Укрепи меня, да бодрствую в пении, уныния сон отгоняя. Связанного узами грехопадений мольбами Твоими освободи, Божия Невеста. Ночью и днем сохраняй меня, избавляя от нападений врагов. Родившая Бога, жизни Подателя, меня, умерщвленного страстями, оживи. Родившая Свет Невечерний, душу мою ослепшую просвети. О дивный Чертог Владыки, домом Духа Божественного соделай меня. Врача родившая, уврачуй многолетние страсти души моей. Носимого по волнам житейскою бурею, к пути покаяния меня направь. Избавь меня от огня вечного, злого червя и преисподней. Да не окажусь я радостью бесам, во многих грехах повинный. Обнови меня, Пренепорочная, одряхлевшего от неприметных согрешений. Яви меня непричастным всякой муке и всех Владыку умоли. Удостой меня со всеми святыми приобщиться к небесному веселью. Пресвятая Дева, услышь глас непотребного раба Твоего! Даруй мне потоки слез, Пречистая, души моей скверну очищающие. Стенания от сердца приношу Тебе непрестанно, – усердствуй, Владычица! Молитвенное служение моё прими и к Богу милосердному принеси. Вознесенная выше Ангелов, над мирским смятением меня вознеси. Светоносная Скиния небесная, духовную благодать во мне направь. Руки и уста возношу ко хвале, оскверненные скверною, Всенепорочная. От душепагубных мерзостей избавь меня, Христа прилежно умоляя, – Ему честь и поклонение подобает ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0046", "section": "service", "who": "rubric", "text": "Молитва 8-я, ко Господу нашему Иисусу Христу"},
  {"id": "ru-mol-0047", "section": "service", "who": "reader", "text": "Многомилостивый и всемилостивый Боже мой, Господи Иисусе Христе, по великой любви Ты сошел и воплотился, чтобы спасти всех. И снова, Спаситель, молю Тебя: спаси меня по благодати! Ведь если бы Ты за дела мог спасти меня, это не было бы благодатью и даром, но скорее долгом. Так, богатый состраданием и неизреченный в милости, – ибо Ты сказал, о Христе мой: «Верующий в Меня будет жить и не увидит смерти вовеки». Если же вера в Тебя спасает потерявших надежду, – то вот, я верую, спаси меня, ибо Ты – Бог мой и Создатель. Да зачтется же мне вера вместо дел, Боже мой, ибо не найдешь Ты никаких дел, оправдывающих меня. Но вместо всех их пусть будет довольно этой веры моей, – пусть она отвечает, пусть она оправдает меня, пусть она покажет меня участником славы Твоей вечной. Да не похитит же меня сатана и да не похвалится тем, что отторг меня от Твоей, Слово Божие, руки и ограды. Но хочу ли, или не хочу, спаси меня, Христе, Спаситель мой, скоро приди ко мне на помощь, поспеши, я погибаю, – ибо Ты Бог мой от чрева матери моей! Сподоби меня, Господи, ныне возлюбить Тебя, как я возлюбил некогда тот самый грех, и вновь послужить Тебе без лености, усердно, как я прежде поработал на сатану – обольстителя. Буду же постоянно служить Тебе, Господу и Богу моему Иисусу Христу во все дни жизни моей, ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0048", "section": "service", "who": "rubric", "text": "Молитва 9-я, к Ангелу-Хранителю"},
  {"id": "ru-mol-0049", "section": "service", "who": "reader", "text": "Святой Ангел, поставленный блюсти мою бедную душу и несчастную жизнь, не оставь меня, грешного, и не отступи от меня за невоздержание моё. Не дай возможности злому демону властвовать надо мною посредством смертного тела сего. Возьми крепко несчастную и опустившуюся мою руку и выведи меня на путь спасения. О святой Ангел Божий, хранитель и покровитель бедной моей души и тела! Прости мне всё, чем я оскорбил Тебя во все дни жизни моей, и если чем согрешил я в прошедшую ночь сию, защити меня в настоящий день и сохрани меня от всякого искушения вражеского, чтобы мне никаким грехом не прогневать Бога, и молись за меня Господу, да утвердит Он меня в страхе Своем и покажет меня рабом, достойным Своей благости. Аминь."},
  {"id": "ru-mol-0050", "section": "service", "who": "rubric", "text": "Молитва 10-я, ко Пресвятой Богородице"},
  {"id": "ru-mol-0051", "section": "service", "who": "reader", "text": "Пресвятая Владычица моя, Богородица, святыми Твоими и всесильными мольбами отгони от меня смиренного и несчастного раба Твоего уныние, забвение, неразумие, нерадение и все скверные, лукавые и хульные помышления от бедного моего сердца и от помраченного ума моего, и погаси пламя страстей моих, ибо я убог и несчастен. И избавь меня от многих и пагубных воспоминаний и намерений, и от всех дел злых освободи меня, ибо благословляют Тебя все роды и славится многочтимое имя Твоё во веки веков. Аминь."},
  {"id": "ru-mol-0052", "section": "service", "who": "rubric", "text": "Молитвенное призывание святого, имя которого носишь"},
  {"id": "ru-mol-0053", "section": "service", "who": "reader", "text": "Моли Бога о мне, святой угодник Божий (имя)*, ибо я усердно к тебе прибегаю, скорому помощнику и молитвеннику о душе моей."},
  {"id": "ru-mol-0054", "section": "service", "who": "reader", "text": "*или: святой апостол (мученик, святитель – и т.п.) (имя)"},
  {"id": "ru-mol-0055", "section": "service", "who": "rubric", "text": "Песнь Пресвятой Богородице"},
  {"id": "ru-mol-0056", "section": "service", "who": "reader", "text": "Богородица Дева, радуйся; благодатная Мария, Господь с Тобою! Благословенна ты между женами и благословен Плод чрева Твоего, ибо Ты родила Спасителя душ наших."},
  {"id": "ru-mol-0057", "section": "service", "who": "rubric", "text": "Тропарь Кресту и молитва за Отечество"},
  {"id": "ru-mol-0058", "section": "service", "who": "reader", "text": "Спаси, Господи, людей Твоих / и благослови наследие Твоё, / победы над врагами даруя / и Крестом Твоим сохраняя Твой народ."},
  {"id": "ru-mol-0059", "section": "service", "who": "rubric", "text": "Молитва о живых"},
  {"id": "ru-mol-0060", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй отца моего духовного (имя), родителей моих (имена), родственников (имена), начальников, наставников, благодетелей (имена их) и всех православных христиан."},
  {"id": "ru-mol-0061", "section": "service", "who": "rubric", "text": "Молитва об усопших"},
  {"id": "ru-mol-0062", "section": "service", "who": "reader", "text": "Упокой, Господи, души усопших рабов Твоих: родителей моих (имена), родственников, благодетелей (имена их), и всех православных христиан, и прости им все согрешения вольные и невольные, и даруй им Царство Небесное."},
  {"id": "ru-mol-0063", "section": "service", "who": "rubric", "text": "Если можешь, читай вместо кратких молитв о живых и усопших этот помянник:"},
  {"id": "ru-mol-0064", "section": "service", "who": "rubric", "text": "О живых"},
  {"id": "ru-mol-0065", "section": "service", "who": "reader", "text": "Помяни, Господи Иисусе Христе, Боже наш, милости и щедроты, от века Тебе присущие, ради которых Ты и вочеловечился, и распятие и смерть, для спасения право верующих в Тебя, претерпеть благоволил; и воскрес из мертвых, вознесся на небеса и восседаешь справа от Бога Отца, и призираешь на смиренные мольбы всем сердцем призывающих Тебя; приклони ухо Твое, и услышь смиренное моление меня, непотребного раба Твоего, как аромат благоухания духовного, Тебе за весь народ Твой приносящего. И во-первых помяни Церковь Твою Святую, Соборную и Апостольскую, Которую Ты приобрел драгоценною Твоею Кровью, и утверди, и укрепи, и расширь, умножь, умиротвори, и непреоборимой вратами ада навеки сохрани; разделения Церквей прекрати, дерзость язычников обуздай, и ересей восстание скоро разрушь и искорени, и в ничто силою Святого Твоего Духа обрати. (Поклон)"},
  {"id": "ru-mol-0066", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй богохранимую страну нашу, власти и воинство ее, дабы нам тихую и безмятежную жизнь проводить во всяком благочестии и чистоте. (Поклон)"},
  {"id": "ru-mol-0067", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй Великого Господина и Отца нашего Святейшего Патриарха (имя), преосвященных митрополитов, архиепископов и епископов православных, также иереев и диаконов, и всех служителей церковных, которых Ты поставил пасти духовное Твое стадо, и по молитвам их помилуй и спаси меня, грешного. (Поклон)"},
  {"id": "ru-mol-0068", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй отца моего духовного (имя его), и по святым его молитвам прости мои согрешения. (Поклон)"},
  {"id": "ru-mol-0069", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй родителей моих (имена их), братьев и сестер, и родных мне по плоти, и всех близких роду моему, и друзей, и даруй им земные Твои и небесные блага. (Поклон)"},
  {"id": "ru-mol-0070", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй по множеству щедрот Твоих священноиноков, иноков же и инокинь, и всех в девстве же и благоговении и постничестве живущих в монастырях, в пустынях, в пещерах, горах, столпах, затворах, расселинах каменных, островах морских, и на всяком месте владычества Твоего правоверно живущих и благочестно служащих Тебе, и молящихся Тебе. Облегчи им тяготу, и утеши их скорбь, и к подвигу силу и крепость от Тебя им подай, и молитвами их даруй мне оставление грехов. (Поклон)"},
  {"id": "ru-mol-0071", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй старцев и юных, нищих и сирот, и вдов, и пребывающих в болезни и в печалях, в бедах и скорбях, тяжких обстоятельствах и плену, в темницах и заточении, особенно же рабов Твоих, ради Тебя и веры православной гонимых от язычников, безбожников, от отступников и от еретиков, и помяни их, посети, укрепи, утешь, и вскоре силою Твоею облегчение, свободу и избавление им подай. (Поклон)"},
  {"id": "ru-mol-0072", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй оказывающих нам благодеяния, жалеющих и насыщающих нас, милосердных к нам, и заповедавших нам, недостойным, молиться о них, и успокаивающих нас, и поступи с ними милостиво, даруя им всё, необходимое для спасения и получения вечных благ. (Поклон)"},
  {"id": "ru-mol-0073", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй посланных на службу, и путешествующих отцов и братьев наших, и всех православных христиан. (Поклон)"},
  {"id": "ru-mol-0074", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй тех, кого я по неразумию своему соблазнил, и от пути спасительного отвратил, и к делам злым и неподобающим привлек; Божественным Твоим Промыслом к пути спасения их снова обрати. (Поклон)"},
  {"id": "ru-mol-0075", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй ненавидящих и обижающих меня, и причиняющих мне неприятности, и не допусти им погибнуть из-за меня, грешного. (Поклон)"},
  {"id": "ru-mol-0076", "section": "service", "who": "reader", "text": "Отступивших от православной веры и погибельными ересями ослепленных светом Твоего познания просвети и к Святой Твоей Апостольской Соборной Церкви причти. (Поклон)"},
  {"id": "ru-mol-0077", "section": "service", "who": "rubric", "text": "Об усопших"},
  {"id": "ru-mol-0078", "section": "service", "who": "reader", "text": "Помяни, Господи, от жизни сей отошедших святейших патриархов, преосвященных митрополитов, архиепископов и епископов православных, всех, в сане иерейском, и в клире церковном, и монашеском звании Тебе послуживших, и в вечных Твоих обителях со святыми упокой. (Поклон)"},
  {"id": "ru-mol-0079", "section": "service", "who": "reader", "text": "Помяни, Господи, души усопших рабов Твоих, родителей моих (имена их), и всех родных по плоти; и прости все их согрешения вольные и невольные, даруя им Царство Небесное, и причастие вечных Твоих благ, и Твоей бесконечной и блаженной жизни наслаждение. (Поклон)"},
  {"id": "ru-mol-0080", "section": "service", "who": "reader", "text": "Помяни, Господи, и всех с надеждою на воскресение и жизнь вечную усопших: отцов и братьев наших и сестер, и здесь и повсюду лежащих православных христиан, и со святыми Твоими, там, где сияет свет лица Твоего, их посели, и нас помилуй, как Благой и Человеколюбец. Аминь. (Поклон)"},
  {"id": "ru-mol-0081", "section": "service", "who": "reader", "text": "Подай, Господи, отпущение грехов всем прежде отошедшим в вере и надежде воскресения: отцам, братьям и сестрам нашим и сотвори им вечную память. (Трижды)"},
  {"id": "ru-mol-0082", "section": "service", "who": "rubric", "text": "Окончание молитв"},
  {"id": "ru-mol-0083", "section": "service", "who": "reader", "text": "Поистине достойно прославлять Тебя, Богородицу, Всегда Блаженную и Непорочную и Матерь Бога нашего. Ты достойна большей почести, чем Херувимы, и по славе Своей несравненно выше Серафимов, девственно Бога-Слово родившую, и как истинную Богородицу мы Тебя величаем."},
  {"id": "ru-mol-0084", "section": "service", "who": "reader", "text": "Господи Иисусе Христе, Сын Божий, по молитвам Пречистой Твоей Матери, преподобных и богоносных отцов наших и всех святых, помилуй нас. Аминь."},
  {"id": "ru-mol-0085", "section": "service", "who": "rubric", "text": "Выделенные от основного текста примечания и названия молитв не читаются во время молитвы."},
  {"id": "ru-mol-0086", "section": "service", "who": "rubric", "text": "В молитвословах и богослужебных книгах часто пишут кратко «Слава», «И ныне», но читать надо полностью: «Слава Отцу и Сыну и Святому Духу», «И ныне и присно и во веки веков. Аминь»"},
  {"id": "ru-mol-0087", "section": "service", "who": "rubric", "text": "В церковнославянском языке нет звука ё, а поэтому надо читать «зовем», а не «зовём», «твое», а не «твоё», «мое», а не «моё» и т. д."},
  {"id": "ru-mol-0088", "section": "service", "who": "rubric", "text": "В Православном молитвослове – 2-е изд., испр. и перераб. – СТСЛ, 2012. – 192 с. – приводится: в делание заповедей Его."},
  {"id": "ru-mol-0089", "section": "service", "who": "reader", "text": "Во имя Отца, и Сына, и Святого Духа. Аминь."},
  {"id": "ru-mol-0090", "section": "service", "who": "rubric", "text": "Затем немного подожди, пока все чувства твои не придут в тишину и мысли твои не оставят все земное, и тогда произноси следующие молитвы, без поспешности и со вниманием сердечным:"},
  {"id": "ru-mol-0091", "section": "service", "who": "rubric", "text": "Молитва мытаря (Лк.18:13)"},
  {"id": "ru-mol-0092", "section": "service", "who": "reader", "text": "Боже, будь милостив ко мне грешной."},
  {"id": "ru-mol-0093", "section": "service", "who": "rubric", "text": "Начало обычное"},
  {"id": "ru-mol-0094", "section": "service", "who": "rubric", "text": "Молитва предначинательная"},
  {"id": "ru-mol-0095", "section": "service", "who": "reader", "text": "Господи Иисусе Христе, Сын Божий, по молитвам Пречистой Твоей Матери и всех святых, помилуй нас. Аминь."},
  {"id": "ru-mol-0096", "section": "service", "who": "rubric", "text": "Молитва Святому Духу"},
  {"id": "ru-mol-0097", "section": "service", "who": "reader", "text": "Царь Небесный, Утешитель (Советник, Наставник), Дух истины, везде сущий (находящийся) и все наполняющий (присутствием Своим), Сокровище благ и Податель жизни, прииди и поселись в нас (среди нас), очисти нас от всякого греха и спаси, Преблагий, души наши."},
  {"id": "ru-mol-0098", "section": "service", "who": "rubric", "text": "Трисвятое"},
  {"id": "ru-mol-0099", "section": "service", "who": "reader", "text": "Святой Боже, Святой Крепкий, Святой Бессмертный, помилуй нас."},
  {"id": "ru-mol-0100", "section": "service", "who": "reader", "text": "Слава Отцу и Сыну и Святому Духу, и ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0101", "section": "service", "who": "rubric", "text": "Молитва ко Пресвятой Троице"},
  {"id": "ru-mol-0102", "section": "service", "who": "reader", "text": "Пресвятая Троица, помилуй нас. Господи, очисти грехи наши. Владыка, прости беззакония наши. Святый, посети и исцели немощи наши, имени Твоего ради."},
  {"id": "ru-mol-0103", "section": "service", "who": "reader", "text": "Слава Отцу, и Сыну, и Святому Духу, и ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0104", "section": "service", "who": "rubric", "text": "Молитва Господня"},
  {"id": "ru-mol-0105", "section": "service", "who": "reader", "text": "Отче наш, Который на небесах! Да святится имя Твое, да приидет Царствие Твое; да будет воля Твоя и на земле, как на небе; хлеб наш насущный дай нам на сей день; и прости нам долги наши, как и мы прощаем должникам нашим; и не введи нас в искушение, но избавь нас от лукавого."},
  {"id": "ru-mol-0106", "section": "service", "who": "rubric", "text": "Тропари Троичные"},
  {"id": "ru-mol-0107", "section": "service", "who": "reader", "text": "Восстав от сна, припадаем к Тебе, Благой, и ангельскую песнь возглашаем Тебе, Сильный: «Свят, Свят, Свят Ты, Боже, по молитвам Богородицы помилуй нас!»"},
  {"id": "ru-mol-0108", "section": "service", "who": "reader", "text": "С постели и от сна Ты поднял меня, Господи! / Ум мой просвети и сердце, / и уста мои отверзи, / чтобы воспевать Тебя, Святая Троица: / «Свят, Свят, Свят Ты, Боже, / по молитвам Богородицы помилуй нас!»"},
  {"id": "ru-mol-0109", "section": "service", "who": "reader", "text": "Внезапно Судия придёт, и дела каждого обнаружатся. Но в страхе воскликнем в полночь: «Свят, Свят, Свят Ты, Боже, по молитвам Богородицы помилуй нас!»"},
  {"id": "ru-mol-0110", "section": "service", "who": "rubric", "text": "Молитва ко Пресвятой Троице"},
  {"id": "ru-mol-0111", "section": "service", "who": "reader", "text": "Восстав от сна, благодарю Тебя, Святая Троица, что по великой Твоей благости и долготерпению, Ты, Боже, не прогневался на меня, ленивую и грешную, и не погубил меня с беззакониями моими, но оказал мне обычное Твоё человеколюбие, и поднял меня, в бесчувствии лежащую, чтобы я рано утром к Тебе обратилась и славословила власть Твою. И ныне просвети взоры мыслей моих, отверзи уста мои, чтобы мне поучаться слову Твоему, и уразумевать заповеди Твои, и творить волю Твою, и петь, прославляя Тебя от сердца, и воспевать всесвятое имя Твоё, Отца, и Сына, и Святого Духа ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0112", "section": "service", "who": "reader", "text": "Придите, поклонимся Царю нашему, Богу."},
  {"id": "ru-mol-0113", "section": "service", "who": "reader", "text": "Придите, поклонимся и припадем ко Христу, Царю, нашему Богу."},
  {"id": "ru-mol-0114", "section": "service", "who": "reader", "text": "Придите, поклонимся и припадем к Самому Христу, Царю и Богу нашему."},
  {"id": "ru-mol-0115", "section": "service", "who": "rubric", "text": "Псалом 50"},
  {"id": "ru-mol-0116", "section": "service", "who": "reader", "text": "Помилуй меня, Боже, по великой милости Твоей и по множеству щедрот Твоих изгладь беззаконие моё; совершенно омой меня от беззакония моего, и от греха моего очисти меня. Ибо беззаконие моё я знаю, и грех мой всегда предо мною. Тебе, Единому, я согрешил и злое пред Тобою сотворил, – да будешь оправдан в словах Твоих и победишь, если вступят с Тобою в суд. Ибо вот, я в беззакониях зачат, и во грехах родила меня мать моя. Ибо вот, Ты истину возлюбил, сокрытое и тайное премудрости Твоей мне открыл. Ты окропишь меня иссопом – и буду очищен; омоешь меня – и сделаюсь белее снега, дашь мне услышать радость и веселие – возрадуются кости униженные. Отврати лицо Твоё от грехов моих и все беззакония мои изгладь. Сердце чистое сотвори во мне, Боже, и Дух Правый обнови внутри меня. Не отринь меня от лица Твоего и Духа Твоего Святого не отними от меня. Возврати мне радость спасения Твоего и Духом Владычественным утверди меня. Научу беззаконных путям Твоим, и нечестивые к Тебе обратятся. Избавь меня от кровей, Боже, Боже спасения моего, возрадуется язык мой правде Твоей. Господи, Ты откроешь уста мои, и уста мои возвестят хвалу Твою. Ибо если бы жертвы Ты восхотел, я дал бы её, – к всесожжениям не будешь благоволить. Жертва Богу – дух сокрушённый, сердца сокрушённого и смиренного Бог не презрит. Облагодетельствуй, Господи, во благоволении Твоём Сион, и да будут воздвигнуты стены Иерусалима, – тогда примешь благосклонно жертву правды, возношение и всесожжения, тогда возложат на алтарь Твой тельцов."},
  {"id": "ru-mol-0117", "section": "service", "who": "rubric", "text": "Символ веры"},
  {"id": "ru-mol-0118", "section": "service", "who": "reader", "text": "Верую во единого Бога, Отца, Вседержителя, Творца неба и земли, всего и видимого и невидимого. И во единого Господа Иисуса Христа, Сына Божия, Единородного, от Отца рожденного прежде всех веков, Света от Света, Бога истинного от Бога истинного, рожденного, несотворенного, единосущного Отцу, через Которого всё произошло. Ради нас, людей, и нашего ради спасения сошедшего с небес, и воплотившегося от Духа Святого и Марии Девы, и вочеловечившегося. Распятого же за нас при Понтии Пилате, и страдавшего, и погребенного. И воскресшего в третий день, по Писаниям. И восшедшего на небеса, и сидящего справа от Отца. И снова грядущего со славою судить живых и мёртвых, и Царству Его не будет конца. И в Духа Святого, Господа, Животворящего, от Отца исходящего, со Отцом и Сыном равно поклоняемого и славимого, говорившего чрез пророков. Во единую, святую, соборную и апостольскую Церковь. Признаю одно Крещение для прощения грехов. Ожидаю воскресения мёртвых и жизни будущего века. Аминь."},
  {"id": "ru-mol-0119", "section": "service", "who": "rubric", "text": "Молитвы прп. Макария Великого (†390)"},
  {"id": "ru-mol-0120", "section": "service", "who": "rubric", "text": "Молитва 1-я"},
  {"id": "ru-mol-0121", "section": "service", "who": "reader", "text": "Боже, очисти меня, грешную, ибо я никогда не делала доброго пред Тобою, но избавь меня от зла и да будет во мне воля Твоя, чтобы мне не в осуждение открыть уста мои недостойные и восхвалить имя Твоё святое, Отца, и Сына, и Святого Духа ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0122", "section": "service", "who": "rubric", "text": "Молитва 2-я"},
  {"id": "ru-mol-0123", "section": "service", "who": "reader", "text": "Восстав от сна, полночную песнь приношу Тебе, Спаситель, и, припадая к стопам Твоим, взываю Тебе: не дай мне уснуть во греховной смерти, но сжалься надо мною, добровольно претерпевший распятие, и скоро подними меня, беспечно лежащую, и спаси меня, стоящую пред Тобою на молитве. И после сна ночного пошли мне ясный день безгрешный, Христе Боже, и спаси меня."},
  {"id": "ru-mol-0124", "section": "service", "who": "rubric", "text": "Молитва 3-я"},
  {"id": "ru-mol-0125", "section": "service", "who": "reader", "text": "К Тебе, Владыка Человеколюбец, восстав от сна я спешу, и за дела Тебе угодные принимаюсь, по милосердию Твоему, и молюсь Тебе: помоги мне во всякое время, во всяком деле, и избавь меня от всякой злой превратности в мире сем и от диавольского содействия, и спаси меня, и введи в Царство Твоё вечное. Ибо Ты – мой Творец и всякого блага Промыслитель и Податель. И в Тебе – вся надежда моя, и Тебе славу воссылаю, ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0126", "section": "service", "who": "rubric", "text": "Молитва 4-я"},
  {"id": "ru-mol-0127", "section": "service", "who": "reader", "text": "Господи, Ты по многой Твоей благости и великому милосердию Твоему дал мне, рабе Твоей, минувшее время ночи сей пройти без напасти от всякого зла противника. Ты Сам, Владыка, Творец всего, удостой меня истинным Твоим светом и просвещенным сердцем творить волю Твою, ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0128", "section": "service", "who": "rubric", "text": "Молитва 5-я свт. Василия Великого (†379) к Богу Отцу"},
  {"id": "ru-mol-0129", "section": "service", "who": "reader", "text": "Господи Вседержитель, Боже бесплотных Сил и всякой плоти, на высотах небесных живущий и озирающий долы земные, испытывающий и сердца, и внутренние чувства и сокровенное людей знающий ясно, Безначальный и Вечный Свет, у Которого нет изменения и ни тени перемены! Сам, бессмертный Царь, прими моления наши, которые мы, дерзновенно надеясь на множество милостей Твоих, в настоящее время [ночи] от скверных уст Тебе приносим, и прости нам согрешения наши, делом, и словом, и мыслию, сознательно и по неведению совершённые нами, и очисти нас от всякой скверны плоти и духа, [делая нас храмами Святого Твоего Духа]. И даруй нам с бодрствующим сердцем и трезвым разумом всю ночь нашей нынешней жизни пройти, ожидая пришествия светлого дня явления Единородного Твоего Сына, Господа и Бога и Спасителя нашего Иисуса Христа, когда Он, Судия всех, придёт на землю со славою воздать каждому по делам его; да найдет Он нас не падшими и обленившимися, но бодрствующими и поднявшимися, при исполнении заповедей Его, и готовыми войти с Ним в радость и Божественный чертог Его славы, где празднующих глас непрестанный и невыразимое наслаждение созерцающих несказанную красоту лица Твоего. Ибо Ты истинный Свет, просвещающий и освящающий всё, и Тебя воспевает всё творение во веки веков. Аминь."},
  {"id": "ru-mol-0130", "section": "service", "who": "rubric", "text": "Молитва 6-я свт. Василия Великого (†379) ко Пресвятой Троице"},
  {"id": "ru-mol-0131", "section": "service", "who": "reader", "text": "Тебя благословляем, Всевышний Боже и Господи милости, всегда творящего с нами дела великие и непостижимые, славные же и ужасные, которым нет числа, подавшего нам сон для упокоения немощи нашей и для отдыха от трудов многотрудной плоти. Благодарим Тебя, ибо Ты не погубил нас с беззакониями нашими, но явил Свое человеколюбие, как обычно, и нас, в бесчувствии сна лежащих, воздвиг для славословия могущества Твоего. Поэтому мы молим безмерную Твою благость: просвети наши мысленные очи и ум наш от тяжкого сна беспечности воздвигни. Отверзи уста наши и наполни их хвалою Тебе, дабы мы смогли непоколебимо воспевать, [восхвалять] и славить Тебя, во всех и от всех прославляемого Бога, Безначального Отца со Единородным Твоим Сыном и Всесвятым, и Благим, и Животворящим Твоим Духом, ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0132", "section": "service", "who": "rubric", "text": "Молитва 7-я, ко Пресвятой Богородице"},
  {"id": "ru-mol-0133", "section": "service", "who": "reader", "text": "Воспеваю благодать Твою, Владычица, молю Тебя, ум мой облагодатствуй. Наставь меня ходить право путем Христовых заповедей. Укрепи меня, да бодрствую в пении, уныния сон отгоняя. Связанную узами грехопадений мольбами Твоими освободи, Божия Невеста. Ночью и днем сохраняй меня, избавляя от нападений врагов. Родившая Бога, жизни Подателя, меня, умерщвленную страстями, оживи. Родившая Свет Невечерний, душу мою ослепшую просвети. О дивный Чертог Владыки, домом Духа Божественного соделай меня. Врача родившая, уврачуй многолетние страсти души моей. Носимую по волнам житейскою бурею, к пути покаяния меня направь. Избавь меня от огня вечного, злого червя и преисподней. Да не окажусь я радостью бесам, во многих грехах повинная. Обнови меня, Пренепорочная, одряхлевшую от неприметных согрешений. Яви меня непричастной всякой муке и всех Владыку умоли. Удостой меня со всеми святыми приобщиться к небесному веселью. Пресвятая Дева, услышь глас непотребной рабы Твоей! Даруй мне потоки слез, Пречистая, души моей скверну очищающие. Стенания от сердца приношу Тебе непрестанно, – усердствуй, Владычица! Молитвенное служение моё прими и к Богу милосердному принеси. Вознесенная выше Ангелов, над мирским смятением меня вознеси. Светоносная Скиния небесная, духовную благодать во мне направь. Руки и уста возношу ко хвале, оскверненные скверною, Всенепорочная. От душепагубных мерзостей избавь меня, Христа прилежно умоляя, – Ему честь и поклонение подобает ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0134", "section": "service", "who": "rubric", "text": "Молитва 8-я, ко Господу нашему Иисусу Христу"},
  {"id": "ru-mol-0135", "section": "service", "who": "reader", "text": "Многомилостивый и всемилостивый Боже мой, Господи Иисусе Христе, по великой любви Ты сошел и воплотился, чтобы спасти всех. И снова, Спаситель, молю Тебя: спаси меня по благодати! Ведь если бы Ты за дела мог спасти меня, это не было бы благодатью и даром, но скорее долгом. Так, богатый состраданием и неизреченный в милости, – ибо Ты сказал, о Христе мой: «Верующий в Меня будет жить и не увидит смерти вовеки». Если же вера в Тебя спасает потерявших надежду, – то вот, я верую, спаси меня, ибо Ты – Бог мой и Создатель. Да зачтется же мне вера вместо дел, Боже мой, ибо не найдешь Ты никаких дел, оправдывающих меня. Но вместо всех их пусть будет довольно этой веры моей, – пусть она отвечает, пусть она оправдает меня, пусть она покажет меня участницей славы Твоей вечной. Да не похитит же меня сатана и да не похвалится тем, что отторг меня от Твоей, Слово Божие, руки и ограды. Но хочу ли, или не хочу, спаси меня, Христе, Спаситель мой, скоро приди ко мне на помощь, поспеши, я погибаю, – ибо Ты Бог мой от чрева матери моей! Сподоби меня, Господи, ныне возлюбить Тебя, как я возлюбила некогда тот самый грех, и вновь послужить Тебе без лености, усердно, как я прежде поработала на сатану – обольстителя. Буду же постоянно служить Тебе, Господу и Богу моему Иисусу Христу во все дни жизни моей, ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0136", "section": "service", "who": "rubric", "text": "Молитва 9-я, к Ангелу-Хранителю"},
  {"id": "ru-mol-0137", "section": "service", "who": "reader", "text": "Святой Ангел, поставленный блюсти мою бедную душу и несчастную жизнь, не оставь меня, грешную, и не отступи от меня за невоздержание моё. Не дай возможности злому демону властвовать надо мною посредством смертного тела сего. Возьми крепко несчастную и опустившуюся мою руку и выведи меня на путь спасения. О святой Ангел Божий, хранитель и покровитель бедной моей души и тела! Прости мне всё, чем я оскорбила Тебя во все дни жизни моей, и если чем согрешила я в прошедшую ночь сию, защити меня в настоящий день и сохрани меня от всякого искушения вражеского, чтобы мне никаким грехом не прогневать Бога, и молись за меня Господу, да утвердит Он меня в страхе Своем и покажет меня рабой, достойной Своей благости. Аминь."},
  {"id": "ru-mol-0138", "section": "service", "who": "rubric", "text": "Молитва 10-я, ко Пресвятой Богородице"},
  {"id": "ru-mol-0139", "section": "service", "who": "reader", "text": "Пресвятая Владычица моя, Богородица, святыми Твоими и всесильными мольбами отгони от меня смиренной и несчастной рабы Твоей уныние, забвение, неразумие, нерадение и все скверные, лукавые и хульные помышления от бедного моего сердца и от помраченного ума моего, и погаси пламя страстей моих, ибо я убога и несчастна. И избавь меня от многих и пагубных воспоминаний и намерений, и от всех дел злых освободи меня, ибо благословляют Тебя все роды и славится многочтимое имя Твоё во веки веков. Аминь."},
  {"id": "ru-mol-0140", "section": "service", "who": "rubric", "text": "Молитвенное призывание святой, имя которой носишь"},
  {"id": "ru-mol-0141", "section": "service", "who": "reader", "text": "Моли Бога о мне, святая угодница Божия (имя), ибо я усердно к тебе прибегаю, скорой помощнице и молитвеннице о душе моей."},
  {"id": "ru-mol-0142", "section": "service", "who": "rubric", "text": "Песнь Пресвятой Богородице"},
  {"id": "ru-mol-0143", "section": "service", "who": "reader", "text": "Богородица Дева, радуйся; благодатная Мария, Господь с Тобою! Благословенна ты между женами и благословен Плод чрева Твоего, ибо Ты родила Спасителя душ наших."},
  {"id": "ru-mol-0144", "section": "service", "who": "rubric", "text": "Тропарь Кресту и молитва за Отечество"},
  {"id": "ru-mol-0145", "section": "service", "who": "reader", "text": "Спаси, Господи, людей Твоих и благослови наследие Твоё, победы над врагами даруя и Крестом Твоим сохраняя Твой народ."},
  {"id": "ru-mol-0146", "section": "service", "who": "rubric", "text": "Молитва о живых"},
  {"id": "ru-mol-0147", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй отца моего духовного (имя), родителей моих (имена), родственников (имена), начальников, наставников, благодетелей (имена их) и всех православных христиан."},
  {"id": "ru-mol-0148", "section": "service", "who": "rubric", "text": "Молитва о усопших"},
  {"id": "ru-mol-0149", "section": "service", "who": "reader", "text": "Упокой, Господи, души усопших рабов Твоих: родителей моих (имена), родственников, благодетелей (имена их), и всех православных христиан, и прости им все согрешения вольные и невольные, и даруй им Царство Небесное."},
  {"id": "ru-mol-0150", "section": "service", "who": "rubric", "text": "Если можешь, читай вместо кратких молитв о живых и усопших этот помянник:"},
  {"id": "ru-mol-0151", "section": "service", "who": "rubric", "text": "О живых"},
  {"id": "ru-mol-0152", "section": "service", "who": "reader", "text": "Помяни, Господи Иисусе Христе, Боже наш, милости и щедроты, от века Тебе присущие, ради которых Ты и вочеловечился, и распятие и смерть, для спасения право верующих в Тебя, претерпеть благоволил; и воскрес из мертвых, вознесся на небеса и восседаешь справа от Бога Отца, и призираешь на смиренные мольбы всем сердцем призывающих Тебя; приклони ухо Твое, и услышь смиренное моление меня, непотребной рабы Твоей, как аромат благоухания духовного, Тебе за весь народ Твой приносящей. И во-первых помяни Церковь Твою Святую, Соборную и Апостольскую, Которую Ты приобрел драгоценною Твоею Кровью, и утверди, и укрепи, и расширь, умножь, умиротвори, и непреоборимой вратами ада навеки сохрани; разделения Церквей прекрати, дерзость язычников обуздай, и ересей восстание скоро разрушь и искорени, и в ничто силою Святого Твоего Духа обрати. (Поклон)"},
  {"id": "ru-mol-0153", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй богохранимую страну нашу, власти и воинство ее, дабы нам тихую и безмятежную жизнь проводить во всяком благочестии и чистоте. (Поклон)"},
  {"id": "ru-mol-0154", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй Великого Господина и Отца нашего Святейшего Патриарха (имя), преосвященных митрополитов, архиепископов и епископов православных, также иереев и диаконов, и всех служителей церковных, которых Ты поставил пасти духовное Твое стадо, и по молитвам их помилуй и спаси меня, грешную. (Поклон)"},
  {"id": "ru-mol-0155", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй отца моего духовного (имя его), и по святым его молитвам прости мои согрешения. (Поклон)"},
  {"id": "ru-mol-0156", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй родителей моих (имена их), братьев и сестер, и родных мне по плоти, и всех близких роду моему, и друзей, и даруй им земные Твои и небесные блага. (Поклон)"},
  {"id": "ru-mol-0157", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй по множеству щедрот Твоих священноиноков, иноков же и инокинь, и всех в девстве же и благоговении и постничестве живущих в монастырях, в пустынях, в пещерах, горах, столпах, затворах, расселинах каменных, островах морских, и на всяком месте владычества Твоего правоверно живущих и благочестно служащих Тебе, и молящихся Тебе. Облегчи им тяготу, и утеши их скорбь, и к подвигу силу и крепость от Тебя им подай, и молитвами их даруй мне оставление грехов. (Поклон)"},
  {"id": "ru-mol-0158", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй старцев и юных, нищих и сирот, и вдов, и пребывающих в болезни и в печалях, в бедах и скорбях, тяжких обстоятельствах и плену, в темницах и заточении, особенно же рабов Твоих, ради Тебя и веры православной гонимых от язычников, безбожников, от отступников и от еретиков, и помяни их, посети, укрепи, утешь, и вскоре силою Твоею облегчение, свободу и избавление им подай. (Поклон)"},
  {"id": "ru-mol-0159", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй оказывающих нам благодеяния, жалеющих и насыщающих нас, милосердных к нам, и заповедавших нам, недостойным, молиться о них, и успокаивающих нас, и поступи с ними милостиво, даруя им всё, необходимое для спасения и получения вечных благ. (Поклон)"},
  {"id": "ru-mol-0160", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй посланных на службу, и путешествующих отцов и братьев наших, и всех православных христиан. (Поклон)"},
  {"id": "ru-mol-0161", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй тех, кого я по неразумию своему соблазнила, и от пути спасительного отвратила, и к делам злым и неподобающим привлекла; Божественным Твоим Промыслом к пути спасения их снова обрати. (Поклон)"},
  {"id": "ru-mol-0162", "section": "service", "who": "reader", "text": "Спаси, Господи, и помилуй ненавидящих и обижающих меня, и причиняющих мне неприятности, и не допусти им погибнуть из-за меня, грешной. (Поклон)"},
  {"id": "ru-mol-0163", "section": "service", "who": "reader", "text": "Отступивших от православной веры и погибельными ересями ослепленных светом Твоего познания просвети и к Святой Твоей Апостольской Соборной Церкви причти. (Поклон)"},
  {"id": "ru-mol-0164", "section": "service", "who": "rubric", "text": "О усопших"},
  {"id": "ru-mol-0165", "section": "service", "who": "reader", "text": "Помяни, Господи, от жизни сей отошедших святейших патриархов, преосвященных митрополитов, архиепископов и епископов православных, всех, в сане иерейском, и в клире церковном, и монашеском звании Тебе послуживших, и в вечных Твоих обителях со святыми упокой. (Поклон)"},
  {"id": "ru-mol-0166", "section": "service", "who": "reader", "text": "Помяни, Господи, души усопших рабов Твоих, родителей моих (имена их), и всех родных по плоти; и прости все их согрешения вольные и невольные, даруя им Царство Небесное, и причастие вечных Твоих благ, и Твоей бесконечной и блаженной жизни наслаждение. (Поклон)"},
  {"id": "ru-mol-0167", "section": "service", "who": "reader", "text": "Помяни, Господи, и всех с надеждою на воскресение и жизнь вечную усопших: отцов и братьев наших и сестер, и здесь и повсюду лежащих православных христиан, и со святыми Твоими, там, где сияет свет лица Твоего, их посели, и нас помилуй, как Благой и Человеколюбец. Аминь. (Поклон)"},
  {"id": "ru-mol-0168", "section": "service", "who": "reader", "text": "Подай, Господи, отпущение грехов всем прежде отошедшим в вере и надежде воскресения: отцам, братьям и сестрам нашим и сотвори им вечную память. (Трижды)"},
  {"id": "ru-mol-0169", "section": "service", "who": "rubric", "text": "Окончание молитв"},
  {"id": "ru-mol-0170", "section": "service", "who": "reader", "text": "Поистине достойно прославлять Тебя, Богородицу, Всегда Блаженную и Непорочную и Матерь Бога нашего. Ты достойна большей почести, чем Херувимы, и по славе Своей несравненно выше Серафимов, девственно Бога-Слово родившую, и как истинную Богородицу мы Тебя величаем."},
  {"id": "ru-mol-0171", "section": "service", "who": "reader", "text": "Господи Иисусе Христе, Сын Божий, по молитвам Пречистой Твоей Матери, преподобных и богоносных отцов наших и всех святых, помилуй нас. Аминь."},
  {"id": "ru-mol-0172", "section": "service", "who": "rubric", "text": "Выделенные от основного текста примечания и названия молитв не читаются во время молитвы."},
  {"id": "ru-mol-0173", "section": "service", "who": "rubric", "text": "В молитвословах и богослужебных книгах часто пишут кратко «Слава», «И ныне», но читать надо полностью: «Слава Отцу и Сыну и Святому Духу», «И ныне и присно и во веки веков. Аминь»"},
  {"id": "ru-mol-0174", "section": "service", "who": "rubric", "text": "В церковнославянском языке нет звука ё, а поэтому надо читать «зовем», а не «зовём», «твое», а не «твоё», «мое», а не «моё» и т. д."},
  {"id": "ru-mol-0175", "section": "service", "who": "rubric", "text": "В Православном молитвослове – 2-е изд., испр. и перераб. – СТСЛ, 2012. – 192 с. – приводится: в делание заповедей Его."},
  {"id": "ru-mol-0176", "section": "service", "who": "rubric", "text": "Рекомендуем молитвы"},
  {"id": "ru-mol-0177", "section": "service", "who": "rubric", "text": "282 комментария"},
  {"id": "ru-mol-0178", "section": "service", "who": "rubric", "text": "Православное радио"},
  {"id": "ru-mol-0179", "section": "service", "who": "rubric", "text": "Сейчас в разделе 6741 чел."},
  {"id": "ru-mol-0180", "section": "service", "who": "rubric", "text": "Просмотров 620 млн."},
  {"id": "ru-mol-0181", "section": "service", "who": "rubric", "text": "Молитвословий 2014"},
  {"id": "ru-mol-0182", "section": "service", "who": "rubric", "text": "Пожертвовать"},
  {"id": "ru-mol-0183", "section": "service", "who": "rubric", "text": "©2026 Молитвослов"},
  {"id": "ru-mol-0184", "section": "service", "who": "rubric", "text": "Чтобы вести помянник войдите на сайт"},
  {"id": "ru-mol-0185", "section": "service", "who": "rubric", "text": "Помянник"},
  {"id": "ru-mol-0186", "section": "service", "who": "rubric", "text": "В винительном падеже (Ивана, Марью)В именительном падеже (Иван, Марья)"},
  {"id": "ru-mol-0187", "section": "service", "who": "rubric", "text": "Сохранить"},
];

